function cloud_json(int $status, array $data=[]): void { http_response_code($status); echo json_encode($data, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
function cloud_db(): PDO { global $cfg; static $db; if ($db) return $db; $c=$cfg['db']; return $db=new PDO("mysql:host={$c['host']};dbname={$c['name']};charset={$c['charset']}",$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); }
function cloud_schema(): void { $db=cloud_db(); $db->exec("CREATE TABLE IF NOT EXISTS cloud_folders (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,KEY cloud_folder_parent(parent_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); $db->exec("CREATE TABLE IF NOT EXISTS cloud_files (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,folder_id BIGINT UNSIGNED NULL,original_name VARCHAR(255) NOT NULL,storage_name CHAR(36) NOT NULL,mime_type VARCHAR(190) NOT NULL DEFAULT 'application/octet-stream',extension VARCHAR(32) NOT NULL DEFAULT '',size BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,UNIQUE KEY cloud_storage_name(storage_name),KEY cloud_file_folder(folder_id),KEY cloud_file_name(original_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); $db->exec("CREATE TABLE IF NOT EXISTS cloud_uploads (id CHAR(36) NOT NULL PRIMARY KEY,original_name VARCHAR(255) NOT NULL,storage_name CHAR(36) NOT NULL,mime_type VARCHAR(190) NOT NULL,extension VARCHAR(32) NOT NULL,total_size BIGINT UNSIGNED NOT NULL,chunk_size INT UNSIGNED NOT NULL,received_chunks INT UNSIGNED NOT NULL DEFAULT 0,folder_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'uploading',KEY cloud_upload_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); }
function cloud_auth(): void { if (empty($_SESSION['cloud_auth'])) cloud_json(401,['error'=>'Сессия завершена. Войдите снова.']); }
function cloud_csrf(): string { if (empty($_SESSION['cloud_csrf'])) $_SESSION['cloud_csrf']=bin2hex(random_bytes(24)); return $_SESSION['cloud_csrf']; }
function cloud_check_csrf(): void { if (!hash_equals((string)($_SESSION['cloud_csrf']??''),(string)($_SERVER['HTTP_X_CSRF_TOKEN']??($_POST['csrf']??'')))) cloud_json(419,['error'=>'Обновите страницу и повторите действие.']); }
function cloud_body(): array { $v=json_decode(file_get_contents('php://input') ?: '{}',true); return is_array($v)?$v:[]; }
function cloud_id($id): ?int { return filter_var($id,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]) ?: null; }
function cloud_name(string $name): string { $name=trim(preg_replace('/[\x00-\x1F\x7F]/u','',$name)??''); if ($name==='' || $name==='.' || $name==='..') cloud_json(422,['error'=>'Некорректное имя.']); return mb_substr($name,0,255); }
function cloud_storage(): string { global $cfg; $p=$cfg['storage_path']; if (!is_dir($p)) @mkdir($p,0700,true); if (!is_dir($p)||!is_writable($p)) cloud_json(500,['error'=>'Не настроено хранилище файлов.']); return $p; }
function cloud_uuid(): string { return bin2hex(random_bytes(16)); }
function cloud_ext(string $name): string { return strtolower((string)pathinfo($name,PATHINFO_EXTENSION)); }
function cloud_folder(?int $id): ?array { if ($id===null) return null; $s=cloud_db()->prepare('SELECT * FROM cloud_folders WHERE id=? AND deleted_at IS NULL'); $s->execute([$id]); $r=$s->fetch(); return $r?:null; }
function cloud_file(int $id, bool $trash=false): ?array { $s=cloud_db()->prepare('SELECT * FROM cloud_files WHERE id=?'.($trash?'':' AND deleted_at IS NULL')); $s->execute([$id]); $r=$s->fetch(); return $r?:null; }
function cloud_path(array $row): string { $parts=[$row['original_name']]; $id=$row['folder_id']? (int)$row['folder_id']:null; while($id){$f=cloud_folder($id);if(!$f)break;array_unshift($parts,$f['name']);$id=$f['parent_id']?(int)$f['parent_id']:null;} return implode(' / ',$parts); }
function cloud_relative(array $row): array { return ['id'=>(int)$row['id'],'name'=>$row['original_name'],'mime'=>$row['mime_type'],'extension'=>$row['extension'],'size'=>(int)$row['size'],'folder_id'=>$row['folder_id']?(int)$row['folder_id']:null,'updated'=>$row['updated_at'],'path'=>cloud_path($row)]; }
