  if ($action==='upload-init') { $b=cloud_body();$name=cloud_name((string)($b['name']??''));$size=max(0,(int)($b['size']??0));$folder=cloud_id($b['folder']??null);if($folder!==null&&!cloud_folder($folder))cloud_json(404,['error'=>'Папка не найдена.']);$id=cloud_uuid();$storageName=cloud_uuid();$now=date('Y-m-d H:i:s');$db->prepare('INSERT INTO cloud_uploads(id,original_name,storage_name,mime_type,extension,total_size,chunk_size,folder_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$id,$name,$storageName,(string)($b['type']??'application/octet-stream'),cloud_ext($name),(string)$size,(int)$cfg['chunk_size'],$folder,$now,$now]);$part=cloud_storage().'/.parts';if(!is_dir($part))mkdir($part,0700,true);touch($part.'/'.$id.'.part');cloud_json(200,['upload_id'=>$id,'chunk_size'=>(int)$cfg['chunk_size']]); }
