  if ($action==='download') { $id=cloud_id($_GET['id']??null);$f=$id?cloud_file($id):null;if(!$f||!is_file($storage.'/'.$f['storage_name']))cloud_json(404,['error'=>'Файл не найден.']);$path=$storage.'/'.$f['storage_name'];header('Content-Type: '.($f['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));$dis=isset($_GET['inline'])?'inline':'attachment';header("Content-Disposition: $dis; filename*=UTF-8''".rawurlencode($f['original_name']));readfile($path);exit; }
