  if ($action==='file-delete') { $id=cloud_id(cloud_body()['id']??null);$f=$id?cloud_file($id):null;if(!$f)cloud_json(404,['error'=>'Файл не найден.']);$db->prepare('UPDATE cloud_files SET deleted_at=?,updated_at=? WHERE id=?')->execute([date('Y-m-d H:i:s'),date('Y-m-d H:i:s'),$id]);cloud_json(200,['ok'=>true]); }
