  if ($action==='trash') { $s=$db->query('SELECT * FROM cloud_files WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC LIMIT 100');cloud_json(200,['files'=>array_map('cloud_relative',$s->fetchAll())]); }
  if ($action==='restore') { $id=cloud_id(cloud_body()['id']??null);$f=$id?cloud_file($id,true):null;if(!$f||empty($f['deleted_at']))cloud_json(404,['error'=>'Файл не найден в корзине.']);$db->prepare('UPDATE cloud_files SET deleted_at=NULL,updated_at=? WHERE id=?')->execute([date('Y-m-d H:i:s'),$id]);cloud_json(200,['ok'=>true]); }
